referenceSolutions.javascript:
export function subsets(values          )             {
const sorted=[...values].sort((a,b)=>a-b),out           =[];function visit(i       ,path         ){out.push([...path]);for(let j=i;j<sorted.length;j++)visit(j+1,[...path,sorted[j]]);}visit(0,[]);return out;
}

